with base as (select * from transactions where txn_time >= '2023-09-01' and is_flagged and is_flagged), amount_bucket_summary as (select case when amount >= 3900 then 'high' when amount >= 1000 then 'mid' else 'low' end amount_bucket, txn_type, min(txn_time) min_txn_time from base group by case when amount >= 3900 then 'high' when amount >= 1000 then 'mid' else 'low' end, txn_type) select * from amount_bucket_summary
